<template><div><DetailSection title="主体与联系人"><FieldRow label="主体类型" :value="status(profile.subjectType||extra.subjectType)"/><FieldRow label="主体名称" :value="profile.legalName"/><FieldRow label="统一社会信用代码" :value="profile.legalCode"/><FieldRow label="法定代表人／经营者" :value="profile.legalPerson"/><FieldRow label="联系人" :value="profile.contactName"/><FieldRow label="经营联系电话" :value="profile.phone"/></DetailSection><DetailSection title="店铺经营资料"><FieldRow label="店铺名称" :value="profile.storeName"/><FieldRow label="营业时间" :value="profile.businessHours||extra.businessHours"/><FieldRow label="所在地区" :value="regionPath" wide/><FieldRow label="详细地址" :value="profile.address" wide/><FieldRow label="店铺介绍" :value="profile.description" wide/></DetailSection><DetailSection v-if="range" title="经营范围" :grid="false"><CategoryNames :ids="profile.categoryIds||[]" :purpose="purpose"/></DetailSection></div></template>
<script>import {uiRead} from '@/api/stage1-usability';import {status} from '../display.cjs';import DetailSection from './DetailSection';import FieldRow from './FieldRow';import CategoryNames from './CategoryNames';export default {components:{DetailSection,FieldRow,CategoryNames},props:{profile:{type:Object,default:()=>({})},purpose:{type:String,default:'eligibility'},range:{type:Boolean,default:true}},data:()=>({regionPath:'未提供',ticket:0}),computed:{extra(){return this.profile.extra||{};}},watch:{profile:{immediate:true,deep:true,handler(){this.resolveRegion();}}},beforeDestroy(){this.ticket++;},methods:{status,async resolveRegion(){const ticket=++this.ticket;const values=['provinceCode','cityCode','districtCode'].map(k=>this.profile[k]||this.extra[k]).filter(Boolean);this.regionPath=values.length?'区划名称读取中…':'未提供';if(!values.length)return;try{const rows=await uiRead('/region-names',{codes:values.join(',')});if(ticket!==this.ticket)return;this.regionPath=values.map(code=>{const r=rows.find(x=>x.code===code);return r?r.name:'名称未提供（'+code+'）';}).join(' / ');}catch(e){if(ticket===this.ticket)this.regionPath='区划名称无法读取：'+e.message+'（'+values.join(' / ')+'）';}}}};</script>
